(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-797":{scenario:{company:"Khách sạn Hạc Trắng Bờ Hồ",supervisor:{name:"Ngô Thị Thu Trang",role:{vi:"Giám đốc Khối Phòng",en:"Rooms Division Manager"}},ref_code:"HK-2611",title:{vi:"Đúng trạng thái phòng. Đúng nhân lực. Đúng chuẩn vệ sinh.",en:"Right room status. Right staffing. Right hygiene standard."},brief:{vi:"Bạn chốt kế hoạch buồng phòng HK-2611 cho ca sáng mai: dự báo 70 phòng khách trả và 98 phòng khách ở tiếp. Định mức mô phỏng: phòng khách trả 45 phút, phòng ở tiếp 25 phút; mỗi nhân viên buồng có 420 phút làm phòng thực tế trong ca 8 giờ. Phòng 1603 bị thấm nước trần, kỹ thuật báo cần sửa trên 48 giờ. Sửa trạng thái phòng 1603 và số nhân viên buồng cần phân công, rồi lập báo cáo có căn cứ.",en:"You are finalising housekeeping plan HK-2611 for tomorrow's morning shift: 70 departure rooms and 98 stayover rooms are forecast. Training standards: 45 minutes per departure, 25 minutes per stayover; each room attendant has 420 minutes of actual cleaning time in an 8-hour shift. Room 1603 has a ceiling leak and engineering needs more than 48 hours to fix it. Correct the status of room 1603 and the number of attendants, then write an evidence-based report."},reference_title:{vi:"Quy định trạng thái phòng & định mức lao động đã duyệt · HK-2611",en:"Approved room status rules & labour standards · HK-2611"},fields:[{id:"ROOM_STATUS",label:{vi:"Trạng thái phòng 1603",en:"Room 1603 status"},initial:"OOS",expected:"OOO",choices:["VD","OOS","OOO"],reference:"Quy định mã trạng thái phòng",hint:{vi:"Phòng phải sửa chữa lớn, kéo dài và không thể bán cần rút khỏi quỹ phòng bán, khác với lỗi nhỏ tạm thời.",en:"A room needing major, lengthy repair that cannot be sold must leave sellable inventory, unlike a minor temporary issue."}},{id:"RA_COUNT",label:{vi:"Số nhân viên buồng ca sáng",en:"Room attendants for the morning shift"},initial:"12",expected:"14",reference:"Bảng định mức lao động buồng phòng",ref_value:{vi:"70 phòng khách trả x 45 phút; 98 phòng ở tiếp x 25 phút; 420 phút mỗi nhân viên",en:"70 departures x 45 minutes; 98 stayovers x 25 minutes; 420 minutes per attendant"},hint:{vi:"Dùng thời gian làm phòng thực tế, không dùng cả 8 giờ ca, và làm tròn lên số nguyên.",en:"Use actual cleaning time, not the full 8-hour shift, and round up to a whole number."}}],sop32:{vi:"Số nhân viên buồng = (số phòng khách trả x 45 + số phòng ở tiếp x 25) / 420 phút làm phòng thực tế mỗi ca, làm tròn lên số nguyên; phòng sửa chữa dài ngày không đưa vào kế hoạch (định mức mô phỏng).",en:"Room attendants = (departures x 45 + stayovers x 25) / 420 actual cleaning minutes per shift, rounded up to a whole number; long-repair rooms are excluded from the plan (training standards)."},context:{label:"PMS HSK / HK-2611",metrics:[{label:{vi:"Phòng khách trả",en:"Departures"},value:"70"},{label:{vi:"Phòng ở tiếp",en:"Stayovers"},value:"98"},{label:{vi:"Phút làm phòng mỗi ca",en:"Cleaning minutes per shift"},value:"420"}]},crisis:{vi:"Khách phòng 1208 báo có rệp giường và gửi ảnh. Quản lý tiền sảnh nhắn: “Tối nay hết phòng, xịt thuốc nhanh rồi bán lại 1208 cho khách đến muộn, đừng ghi vào sổ để khỏi ảnh hưởng điểm đánh giá.”",en:"The guest in room 1208 reports bed bugs and sends photos. The front office manager writes: “We're full tonight. Spray it quickly and resell 1208 to a late arrival, and don't log it so our ratings aren't hurt.”"},options:{safe:{vi:"Khóa phòng 1208 không bán, xử lý theo quy trình kiểm soát côn trùng với đơn vị chuyên nghiệp, báo Giám đốc Khối Phòng, ghi sổ đầy đủ và đề xuất phòng thay thế cho khách.",en:"Block room 1208 from sale, treat it under the pest control procedure with a licensed contractor, inform the Rooms Division Manager, log it fully and offer the guest another room."},shortcut:{vi:"Xịt thuốc nhanh, bán lại phòng 1208 tối nay và không ghi vào sổ.",en:"Spray quickly, resell room 1208 tonight and leave it out of the log."},wait:{vi:"Để phòng 1208 nguyên trạng và chờ ca sau tự quyết định.",en:"Leave room 1208 as it is and let the next shift decide."}},questions:{vi:["Vì sao bạn đổi mã trạng thái phòng 1603? Thông tin nào của bộ phận kỹ thuật chứng minh lựa chọn đó?","Trình bày cách tính số nhân viên buồng và cách xử lý khi bị yêu cầu bán lại phòng có côn trùng gây hại."],en:["Why did you change the status code of room 1603? Which engineering information supports your choice?","Explain how you calculated the number of attendants and how you handle pressure to resell a room with pests."]},hints:{vi:["Đọc thời gian sửa chữa dự kiến của kỹ thuật rồi đối chiếu với định nghĩa từng mã trạng thái phòng.","Theo SOP mục 3.2: quy đổi khối lượng phòng ra phút, chia cho phút làm phòng thực tế và làm tròn lên.","Đọc lại SOP mục 4.2: phòng có côn trùng gây hại phải khóa, xử lý và ghi nhận, mọi áp lực bán phải báo cáo."],en:["Read engineering's expected repair time and compare it with the definition of each status code.","Per SOP 3.2: convert the room workload to minutes, divide by actual cleaning minutes and round up.","Re-read SOP 4.2: a room with pests must be blocked, treated and logged; escalate any pressure to sell it."]}},learning:{summary:{vi:"Quản lý buồng phòng khách sạn chịu trách nhiệm vệ sinh, bảo dưỡng và trình bày toàn bộ phòng khách, khu công cộng, đồ vải và giặt là. Người quản lý lập kế hoạch nhân lực theo dự báo, kiểm soát trạng thái phòng, hóa chất, chi phí, đồ thất lạc và phối hợp với tiền sảnh, kỹ thuật để phòng luôn sẵn sàng bán. Nghề đòi hỏi con mắt tỉ mỉ, kỹ năng điều phối đội ngũ lớn, hiểu an toàn lao động và kiên định với tiêu chuẩn vệ sinh.",en:"A hotel housekeeping manager is responsible for cleaning, upkeep and presentation of all guest rooms, public areas, linen and laundry. The manager plans staffing from forecasts, controls room status, chemicals, costs and lost property, and works with the front office and engineering so rooms are always ready to sell. The role needs an eye for detail, skill in leading a large team, knowledge of workplace safety and firmness on hygiene standards."},responsibilities:{vi:["Lập kế hoạch nhân lực, phân công khu vực theo dự báo phòng khách trả và ở tiếp.","Kiểm tra phòng, khu công cộng và bảo đảm phòng đạt chuẩn trước khi báo sạch.","Quản lý mã trạng thái phòng, đối chiếu chênh lệch với tiền sảnh và báo hỏng cho kỹ thuật.","Quản lý đồ vải, hóa chất, vật tư, đồ thất lạc và chi phí buồng phòng.","Huấn luyện tiêu chuẩn vệ sinh, an toàn hóa chất, an toàn lao động cho nhân viên."],en:["Plan staffing and assign sections from departure and stayover forecasts.","Inspect rooms and public areas and ensure standards before releasing rooms as clean.","Manage room status codes, resolve discrepancies with the front office and report defects to engineering.","Control linen, chemicals, supplies, lost property and housekeeping costs.","Train staff on cleaning standards, chemical safety and workplace safety."]},competencies:[{name:{vi:"Lập kế hoạch nhân lực",en:"Labour planning"},desc:{vi:"Quy đổi khối lượng phòng ra thời gian, phân công đủ người và kiểm soát giờ làm thêm.",en:"Convert room workload to time, staff adequately and control overtime."}},{name:{vi:"Quản lý trạng thái phòng",en:"Room status control"},desc:{vi:"Dùng đúng mã VC, VD, OC, OOO, OOS và xử lý chênh lệch với tiền sảnh kịp thời.",en:"Use VC, VD, OC, OOO and OOS correctly and resolve front office discrepancies quickly."}},{name:{vi:"Tiêu chuẩn vệ sinh",en:"Hygiene standards"},desc:{vi:"Kiểm tra phòng theo danh mục chuẩn, phát hiện côn trùng gây hại và lỗi bảo dưỡng.",en:"Inspect rooms with standard checklists and detect pests and maintenance defects."}},{name:{vi:"An toàn hóa chất & lao động",en:"Chemical & workplace safety"},desc:{vi:"Áp dụng phiếu an toàn hóa chất, trang bị bảo hộ và kỹ thuật làm việc an toàn.",en:"Apply safety data sheets, protective equipment and safe working techniques."}},{name:{vi:"Trung thực & trách nhiệm",en:"Honesty & accountability"},desc:{vi:"Ghi sổ đúng sự thật, không báo sạch khi chưa đạt và bảo vệ sức khỏe của khách.",en:"Log the truth, never release rooms that fail inspection and protect guest health."}}],knowledge:{vi:["TCVN 4391:2015 về xếp hạng khách sạn: yêu cầu về buồng ngủ, vệ sinh và dịch vụ buồng.","Luật An toàn, vệ sinh lao động số 84/2015/QH13: trang bị bảo hộ và huấn luyện an toàn cho người lao động.","Quản lý hóa chất theo phiếu an toàn hóa chất (SDS) và hệ thống GHS; không pha trộn chất tẩy chứa clo với axit.","Mã trạng thái phòng VC, VD, OC, OOO, OOS và quy trình đối chiếu với tiền sảnh.","Quản lý dịch hại tổng hợp (IPM) và quy trình xử lý rệp giường trong khách sạn.","Định mức lao động, mức tồn đồ vải chuẩn và chi phí buồng phòng trên mỗi đêm phòng có khách."],en:["TCVN 4391:2015 on hotel classification: requirements for guest rooms, hygiene and room service.","Occupational Safety and Health Law No. 84/2015/QH13: protective equipment and safety training.","Chemical management with safety data sheets (SDS) and GHS; never mix chlorine bleach with acid cleaners.","Room status codes VC, VD, OC, OOO and OOS and the front office reconciliation process.","Integrated pest management (IPM) and the bed bug response procedure in hotels.","Labour standards, linen par levels and housekeeping cost per occupied room."]},tools:["Phân hệ buồng phòng trên PMS","Ứng dụng phân công và kiểm tra phòng di động","Hệ thống quản lý đồ vải và giặt là","Bộ định lượng hóa chất tự động","Đèn soi kiểm tra vệ sinh và côn trùng"],kpis:{vi:["Tỷ lệ phòng đạt kiểm tra ngay lần đầu.","Thời gian trung bình làm một phòng khách trả.","Số phàn nàn về vệ sinh trên 1000 đêm phòng có khách.","Chi phí buồng phòng trên mỗi đêm phòng có khách."],en:["Share of rooms passing inspection the first time.","Average cleaning time per departure room.","Cleanliness complaints per 1000 occupied room nights.","Housekeeping cost per occupied room night."]},day:[{time:"07:30",vi:"Họp ca, phân công khu vực theo danh sách phòng khách trả, ở tiếp và phòng VIP.",en:"Hold the briefing and assign sections by departures, stayovers and VIP rooms."},{time:"09:00",vi:"Kiểm tra phòng VIP, phòng khách đến sớm và báo sạch cho tiền sảnh.",en:"Inspect VIP and early arrival rooms and release them to the front office."},{time:"11:00",vi:"Đối chiếu chênh lệch trạng thái phòng với tiền sảnh, báo hỏng cho kỹ thuật.",en:"Reconcile room status discrepancies with the front office and report defects to engineering."},{time:"14:00",vi:"Kiểm tra kho đồ vải, hóa chất, vật tư và sổ đồ thất lạc.",en:"Check linen, chemical and supply stores and the lost property log."},{time:"16:30",vi:"Chốt trạng thái phòng cuối ca, lập báo cáo và kế hoạch nhân lực ngày mai.",en:"Close room status for the shift, write the report and plan tomorrow's staffing."}],mistakes:{vi:["Ghi phòng sửa chữa dài ngày là OOS khiến phòng vẫn nằm trong quỹ phòng bán.","Tính nhân lực theo cả 8 giờ ca thay vì thời gian làm phòng thực tế.","Báo phòng sạch khi chưa kiểm tra hoặc bỏ qua dấu hiệu côn trùng gây hại."],en:["Coding a long-repair room as OOS so it stays in sellable inventory.","Planning staff on the full 8-hour shift instead of actual cleaning time.","Releasing rooms as clean without inspection or ignoring signs of pests."]},career:[{vi:"Nhân viên buồng phòng",en:"Room attendant"},{vi:"Giám sát buồng phòng",en:"Housekeeping supervisor"},{vi:"Quản lý buồng phòng",en:"Housekeeping manager"},{vi:"Giám đốc Khối Phòng",en:"Rooms division manager"}],glossary:[{term:"OOO",vi:"Out of order: phòng hỏng phải sửa chữa lớn, rút khỏi quỹ phòng bán trong thời gian sửa.",en:"Out of order: a room under major repair, removed from sellable inventory during the work."},{term:"OOS",vi:"Out of service: phòng tạm ngừng bán vì lỗi nhỏ, khắc phục nhanh, vẫn nằm trong quỹ phòng.",en:"Out of service: a room briefly held for a minor issue, fixed quickly and still in inventory."},{term:"Discrepancy",vi:"Chênh lệch trạng thái phòng giữa buồng phòng và tiền sảnh cần đối chiếu ngay.",en:"Room status mismatch between housekeeping and the front office that must be resolved at once."},{term:"Par level",vi:"Mức tồn đồ vải chuẩn, thường tính theo số bộ cho mỗi giường để luân chuyển giặt là.",en:"Standard linen stock, usually sets per bed, to keep laundry rotation running."},{term:"Turndown service",vi:"Dịch vụ chỉnh trang phòng buổi tối, chuẩn bị giường ngủ và tiện nghi cho khách.",en:"Evening service that prepares the bed and amenities for the guest."}],quiz:[{q:{vi:"Dự báo 40 phòng khách trả (45 phút) và 60 phòng ở tiếp (25 phút); mỗi nhân viên có 420 phút làm phòng. Cần bao nhiêu nhân viên buồng?",en:"Forecast 40 departures (45 minutes) and 60 stayovers (25 minutes); each attendant has 420 minutes. How many attendants are needed?"},options:{vi:["8 nhân viên","7 nhân viên","9 nhân viên","10 nhân viên"],en:["8 attendants","7 attendants","9 attendants","10 attendants"]},answer:0,explain:{vi:"40 x 45 + 60 x 25 = 3300 phút; 3300 / 420 = 7.86, làm tròn lên được 8 nhân viên.",en:"40 x 45 + 60 x 25 = 3300 minutes; 3300 / 420 = 7.86, rounded up to 8 attendants."}},{q:{vi:"Mã OOS khác OOO ở điểm nào?",en:"How does OOS differ from OOO?"},options:{vi:["OOS là phòng khách đang ở","OOS là phòng bẩn chờ dọn","OOS là phòng sửa chữa lớn dài ngày","OOS là lỗi nhỏ tạm thời, phòng vẫn trong quỹ phòng bán"],en:["OOS is an occupied room","OOS is a dirty room awaiting cleaning","OOS is a long major repair","OOS is a minor temporary issue; the room stays in inventory"]},answer:3,explain:{vi:"OOS dành cho lỗi nhỏ, khắc phục nhanh; OOO dành cho sửa chữa lớn và phòng bị rút khỏi quỹ phòng bán.",en:"OOS covers minor, quick fixes; OOO covers major repairs and removes the room from inventory."}},{q:{vi:"Nhân viên muốn pha chất tẩy chứa clo với chất tẩy cặn axit cho nhanh sạch. Bạn hướng dẫn thế nào?",en:"An attendant wants to mix chlorine bleach with an acid descaler to clean faster. What do you say?"},options:{vi:["Cho phép nếu mở cửa sổ","Cấm pha trộn vì sinh khí độc, dùng đúng hóa chất theo phiếu an toàn","Cho phép nếu đeo khẩu trang y tế","Để nhân viên tự chọn"],en:["Allow it if a window is open","Forbid it because it releases toxic gas; use chemicals per the safety data sheet","Allow it with a surgical mask","Let the attendant decide"]},answer:1,explain:{vi:"Clo trộn với axit giải phóng khí clo độc; chỉ dùng hóa chất đúng hướng dẫn và có bảo hộ phù hợp.",en:"Bleach mixed with acid releases toxic chlorine gas; use chemicals only as instructed with proper protection."}},{q:{vi:"Nhân viên nhặt được đồng hồ đắt tiền khách bỏ quên và đề nghị giữ lại vì khách đã bay. Cách xử lý đúng là gì?",en:"An attendant finds an expensive watch a guest left behind and suggests keeping it as the guest has flown. What is correct?"},options:{vi:["Cho nhân viên giữ","Bán và chia cho cả ca","Ghi sổ đồ thất lạc, niêm phong, cất giữ và liên hệ trả khách","Để lại trong phòng"],en:["Let the attendant keep it","Sell it and share with the shift","Log it as lost property, seal, store it and contact the guest","Leave it in the room"]},answer:2,explain:{vi:"Đồ thất lạc phải ghi sổ, bảo quản an toàn và hoàn trả theo quy trình; giữ lại là chiếm đoạt tài sản.",en:"Lost property must be logged, stored safely and returned per procedure; keeping it is misappropriation."}}],tools_en:["PMS housekeeping module","Mobile room assignment & inspection app","Linen and laundry management system","Automatic chemical dispenser","Inspection torch for hygiene and pests"]}}})})(window.KKR);
